const input = $input.item.json;
const periodo = input.periodo || 'Próximos 14 días';
const esModoPrueba = input.modoPrueba === true || String(input.modoPrueba).toLowerCase() === 'true' || input.modoPrueba === 1;

let payloadParaAPI = {};
let dataOriginalReal = null;

// 1. Escenario Base Real
if (input.inputModelo || input.contextoNegocioSerie || input.data) {
  const dataArr = input.inputModelo || input.contextoNegocioSerie || input.data;
  const arr = Array.isArray(dataArr) ? dataArr : [dataArr];

  // Guardamos la data original INTACTA para el siguiente nodo de análisis
  dataOriginalReal = arr;

  // Limpiamos los datos, pero DEJAMOS PASAR los festivos
  const datosLimpios = arr.map(dia => {
    // Extraemos y descartamos clima, vacaciones y porcentajes. 
    // Como no sacamos "es_festivo" de aquí, viajará al modelo.
    const {
      es_vacaciones_escolares,
      clima,
      ajuste_pct,
      motivo_ajuste,
      ...datosParaModelo
    } = dia;

    return datosParaModelo; // Enviamos esto a la API
  });

  payloadParaAPI = {
    data: datosLimpios,
    periodo
  };
}
// 2. Modo Prueba (Simulación independiente)
else if (esModoPrueba) {
  const hoy = new Date();
  const filas = Array.from({ length: 14 }, (_, i) => {
    const fecha = new Date(hoy);
    fecha.setDate(fecha.getDate() + i + 1);
    return {
      CheckIn: fecha.toISOString().slice(0, 10),
      dias_vista: i + 1,
      ocupacion_actual: 0.50,
      adr_actual: 90,
      lead_time: i + 1,
      Pais_España: 1,
      pickup_7: 2,
      pickup_14: 5,
      ocupacion_anio_anterior: 0.45,
      adr_anio_anterior: 85,
      es_festivo: false // Añadido al modo prueba por si acaso
    };
  });
  payloadParaAPI = { data: filas, periodo: 'Próximos 14 días (Modo Prueba)' };
  dataOriginalReal = filas;
}
else {
  throw new Error("[ERROR CONFIG]: No se recibieron datos de entrada. Activa 'modoPrueba: true' para testear.");
}

return [{
  json: {
    payloadParaAPI,
    periodo,
    dataOriginal: dataOriginalReal,
    contextoNegocioSerie: input.contextoNegocioSerie,
    competenciaResumen: input.competenciaResumen
  }
}];

const datosPrevios = $('Preparar Payload API').item.json;
const respuesta = $input.item.json;

const resultadosLimpios = (respuesta.resultados || []).map(r => {
  const ocupPred = r.ocup_final_predicha ?? 0;
  const ocupAct = r.ocupacion_actual ?? 0;
  const pickup = r.pickup_predicho ?? 0;
  return {
    Fecha: r.Fecha ?? null,
    ocupacion_prevista: Number(ocupPred.toFixed(4)),
    ocupacion_actual: Number(ocupAct.toFixed(4)),
    pickup_previsto: Number(pickup.toFixed(4)),
  };
});

return [{
  json: {
    periodo: datosPrevios.periodo,
    resultados: resultadosLimpios,
    dataOriginal: datosPrevios.dataOriginal,
    contextoNegocioSerie: datosPrevios.contextoNegocioSerie,
    competenciaResumen: datosPrevios.competenciaResumen
  }
}];
